import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="card" style={styles.card}>
        <View style={styles.banner}><Text style={styles.bannerText}>ХЯМДРАЛ</Text></View>
        <Text style={styles.name}>Нарны шил</Text>
      </View>
      {/* энд бичнэ үү: банннерийн булан картаас халихыг таслах */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, justifyContent: "center" },
  card: { backgroundColor: "#fff", borderRadius: 20 },
  banner: { backgroundColor: "#f59e0b", padding: 14 },
  bannerText: { color: "#fff", fontWeight: "bold" },
  name: { padding: 16, fontSize: 16, fontWeight: "600" },
});

registerRootComponent(App);

